CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE quote_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,source_event_id text NOT NULL,payload jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_key text NOT NULL,customer_id text NOT NULL,currency text NOT NULL,version integer NOT NULL,status text NOT NULL,subtotal_minor bigint NOT NULL,discount_minor bigint NOT NULL,tax_minor bigint NOT NULL,total_minor bigint NOT NULL,valid_until timestamptz NOT NULL,requested_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(quote_key,version));
CREATE TABLE quote_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),sku text NOT NULL,description text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0),tax_rate_bps integer NOT NULL CHECK(tax_rate_bps BETWEEN 0 AND 10000));
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),quote_version integer NOT NULL,role text NOT NULL,status text NOT NULL CHECK(status IN('pending','approved','rejected')),actor text,decision_note text,decided_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(quote_id,quote_version,role));
CREATE TABLE quote_acceptance_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),quote_version integer NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(quote_id,quote_version));
CREATE TABLE customer_acceptances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL REFERENCES quotes(id),quote_version integer NOT NULL,acceptance_token_hash text UNIQUE NOT NULL,accepted_by text,accepted_at timestamptz,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','customer_verified')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_number text UNIQUE NOT NULL,quote_id uuid NOT NULL REFERENCES quotes(id),quote_version integer NOT NULL,currency text NOT NULL,total_minor bigint NOT NULL,amount_paid_minor bigint NOT NULL DEFAULT 0,balance_minor bigint NOT NULL,status text NOT NULL,issued_at timestamptz NOT NULL,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),provider text NOT NULL,provider_event_id text NOT NULL,idempotency_key text UNIQUE NOT NULL,invoice_number text NOT NULL,currency text NOT NULL,amount_minor bigint NOT NULL,event_type text NOT NULL,payload jsonb NOT NULL,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','provider_verified')),occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,provider_event_id));
CREATE TABLE reconciliation_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_event_id uuid REFERENCES payment_events(id),invoice_number text,reason text NOT NULL,status text NOT NULL DEFAULT 'open',owner text,resolution_note text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid NOT NULL,attempt_number integer NOT NULL,status text NOT NULL,error_code text,next_retry_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_type,entity_id,attempt_number));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,entity_type text NOT NULL,entity_id uuid,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_quotes_status ON quotes(status,valid_until);CREATE INDEX idx_approvals_pending ON approvals(status,role);CREATE INDEX idx_invoices_open ON invoices(status,balance_minor);CREATE INDEX idx_exceptions_open ON reconciliation_exceptions(status,created_at);
